1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {OutgoingMessage, ListSessionsMessage} from '../../types/messages.js';
6	import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
22	import {log} from '../../shared/logger.js';
23	
24	interface StreamState {
25	  thinkingIndex: number | null;
26	  assistantIndex: number | null;
27	  suppressOutput: boolean;
28	  sentAssistantIndices: number[];
29	}
30	
31	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
32	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore: SessionStore) {
34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
35	  const lock = new PerSessionLock();
36	  return function handleMessage(
37	    ws: WebSocket,
38	    session: ChatSession,
39	    rawMessage: unknown,
40	    signal?: AbortSignal
41	  ): Promise<void> {
42	    const validation = validateMessage(rawMessage);
43	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
44	    if (isUserMessageFrame(rawMessage)) {
45	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
46	    }
47	    // list_sessions is answered off the lock: a history request must not queue behind a streaming answer.
48	    if (validation.valid && validation.data.type === 'list_sessions') {
49	      const msg = validation.data;
50	      return wsErrorHandler(ws, () => handleListSessions(ws, session, sessionStore, msg));
51	    }
52	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
53	    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
54	  };
55	}
56	
57	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
58	async function answerInTurn(
59	  ws: WebSocket,
60	  session: ChatSession,
61	  orchestrator: ChatOrchestrator,
62	  validation: ValidationResult,
63	  signal: AbortSignal | undefined
64	): Promise<void> {
65	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
66	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
67	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
68	    return;
69	  }
70	  const startedAt = Date.now();
71	  try {
72	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
73	  } finally {
74	    endTurn(ws, session, signal, startedAt);
75	  }
76	}
77	
78	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
79	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
80	  if (signal?.aborted) {
81	    log.info('message', 'turn abandoned: its socket closed', {
82	      sessionId: session.sessionId,
83	      elapsedMs: Date.now() - startedAt,
84	    });
85	    return;
86	  }
87	  sendStreamEnd(ws);
88	}
89	
90	async function answerUserMessage(
91	  ws: WebSocket,
92	  session: ChatSession,
93	  orchestrator: ChatOrchestrator,
94	  validation: ValidationResult,
95	  signal: AbortSignal | undefined
96	): Promise<void> {
97	  const message = validation.valid ? validation.data : undefined;
98	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
99	  answerFrame(ws, validation);
100	}
101	
102	function answerFrame(ws: WebSocket, validation: ValidationResult): void {
103	  if (!validation.valid) {
104	    log.warn('message', 'validation failed', {error: validation.error});
105	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
106	    return;
107	  }
108	
109	  const message = validation.data;
110	  if (message.type === 'ping') handlePing(ws, message.timestamp);
111	}
112	
113	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
114	function isUserMessageFrame(rawMessage: unknown): boolean {
115	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
116	}
117	
118	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
119	  try {
120	    await action();
121	  } catch (error) {
122	    const message = error instanceof Error ? error.message : 'Unknown error';
123	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
124	    log.error('message', 'handling error', {error: message, code});
125	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
126	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
127	      return;
128	    }
129	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
130	  }
131	}
132	
133	async function handleUserMessage(
134	  ws: WebSocket,
135	  session: ChatSession,
136	  orchestrator: ChatOrchestrator,
137	  content: string,
138	  signal: AbortSignal | undefined
139	): Promise<void> {
140	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
141	
142	  const userEntry = createUserEntry(content);
143	  const userIndex = appendEntry(session, userEntry);
144	  sendUpsert(ws, userIndex, userEntry);
145	
146	  const parser = new ThinkingTagParser();
147	  const state: StreamState = {
148	    thinkingIndex: null,
149	    assistantIndex: null,
150	    suppressOutput: false,
151	    sentAssistantIndices: [],
152	  };
153	
154	  let textChunkCount = 0;
155	
156	  try {
157	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
158	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
159	      if (signal?.aborted) break;
160	      textChunkCount = logChunk(chunk, textChunkCount);
161	      processChunk(ws, session, state, parser, chunk);
162	    }
163	  } finally {
164	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
165	    flushHeldText(ws, session, state, parser);
166	    closeCutOff(ws, session, state, 'thinkingIndex');
167	    closeCutOff(ws, session, state, 'assistantIndex');
168	  }
169	
170	  if (textChunkCount > 0) {
171	    log.debug('stream', `received ${textChunkCount} text chunks`);
172	  }
173	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
174	}
175	
176	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
177	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
178	  if (chunk.type === 'text') return textChunkCount + 1;
179	
180	  if (textChunkCount > 0) {
181	    log.debug('stream', `received ${textChunkCount} text chunks`);
182	  }
183	
184	  if (chunk.type === 'tool_result') {
185	    log.debug('stream', 'tool_result chunk', {
186	      messageCount: chunk.clientMessages.length,
187	      types: chunk.clientMessages.map(m => m.type),
188	    });
189	    return 0;
190	  }
191	
192	  log.debug('stream', 'chunk', {type: chunk.type});
193	  return 0;
194	}
195	
196	function processChunk(
197	  ws: WebSocket,
198	  session: ChatSession,
199	  state: StreamState,
200	  parser: ThinkingTagParser,
201	  chunk: MessageChunk
202	): void {
203	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
204	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
205	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
206	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
207	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
208	}
209	
210	function processTextChunk(
211	  ws: WebSocket,
212	  session: ChatSession,
213	  state: StreamState,
214	  parser: ThinkingTagParser,
215	  text: string
216	): void {
217	  const segments = parser.push(text);
218	  for (const segment of segments) {
219	    handleTextSegment(ws, session, state, segment);
220	  }
221	}
222	
223	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
224	  if (segment.type === 'thinking') {
225	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
226	    return;
227	  }
228	  commitAndClear(ws, session, state, 'thinkingIndex');
229	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
230	}
231	
